```go
func parseField(text string, idx int) (map[int]bool, error) {
	name := fields[idx].name
	if text == "" { return nil, fmt.Errorf("%s: empty field", name) }
	values := map[int]bool{}
	for _, item := range strings.Split(text, ",") {
		if item == "" { return nil, fmt.Errorf("%s: empty item", name) }
		step := 1
		var base string
		if i := strings.Index(item, "/"); i >= 0 {
			s := item[i+1:]
			if !isDigits(s) || parseInt(s) < 1 {
				return nil, fmt.Errorf("%s: invalid step %s", name, pyRepr(s))
			}
			step = parseInt(s)
			base = item[:i]
		} else {
			base = item
		}
		var start, end int
		switch {
		case base == "*":
			start, end = fields[idx].lo, fields[idx].hi
		case strings.Contains(base, "-"):
			k := strings.Index(base, "-")
			a, b := base[:k], base[k+1:]
			s, err := val(a, idx); if err != nil { return nil, err }
			e, err := val(b, idx); if err != nil { return nil, err }
			if s > e { return nil, fmt.Errorf("%s: range %d-%d is reversed", name, s, e) }
			start, end = s, e
		default:
			start, err := val(base, idx); if err != nil { return nil, err }
			end = start
			if strings.Contains(item, "/") { end = fields[idx].hi }
		}
		for v := start; v <= end; v += step { values[v] = true }
	}
	return values, nil
}
```

