{"content":"package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"

	"example.com/cron/cron"
)

type rec struct {
	Expr       string   `json:"expr"`
	ParseError string   `json:"parse_error"`
	Describe   string   `json:"describe"`
	Nexts      [2]string `json:"nexts"`
}

func refFormat(t time.Time) string {
	s := t.Format("2006-01-02T15:04:05.999999999Z07:00")
	if _, off := t.Zone(); off == 0 {
		s = strings.TrimSuffix(s, "Z") + "+00:00"
	}
	return s
}

func main() {
	data, err := os.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}
	var recs []rec
	if err := json.Unmarshal(data, &recs); err != nil {
		panic(err)
	}
	bad := 0
	for i, r := range recs {
		s, perr := cron.Parse(r.Expr)
		if r.ParseError != "" {
			if perr == nil {
				fmt.Printf("case %d %q: Go parsed OK, python error %q\n", i, r.Expr, r.ParseError)
				bad++
				continue
			}
			if perr.Error() != r.ParseError {
				fmt.Printf("case %d %q: Go error %q, python error %q\n", i, r.Expr, perr, r.ParseError)
				bad++
			}
			continue
		}
		if perr != nil {
			fmt.Printf("case %d %q: Go error %v, python parsed OK\n", i, r.Expr, perr)
			bad++
			continue
		}
		if s.String() != r.Describe {
			fmt.Printf("case %d %q: Go describe %q, python %q\n", i, r.Expr, s.String(), r.Describe)
			bad++
		}
		for _, pair := range r.Nexts {
			base := pair[0]
			want := pair[1]
			t, err := time.Parse("2006-01-02T15:04:05.999999999Z07:00", base)
			if err != nil {
				panic(err)
			}
			got, nerr := s.Next(t)
			if strings.HasPrefix(want, "ERROR:") {
				msg := strings.TrimPrefix(want, "ERROR:")
				if nerr == nil {
					fmt.Printf("case %d %q base %s: Go next %s, python error %q\n", i, r.Expr, base, got, msg)
					bad++
				} else if nerr.Error() != msg {
					fmt.Printf("case %d %q base %s: Go error %q, python error %q\n", i, r.Expr, base, nerr, msg)
					bad++
				}
				continue
			}
			if nerr != nil {
				fmt.Printf("case %d %q base %s: Go error %v, python %s\n", i, r.Expr, base, nerr, want)
				bad++
				continue
			}
			if gs := refFormat(got); gs != want {
				fmt.Printf("case %d %q base %s: Go %s, python %s\n", i, r.Expr, base, gs, want)
				bad++
			}
		}
	}
	fmt.Printf("checked %d cases, %d mismatches\n", len(recs), bad)
}
